package br.com.fintrack.controller;
import br.com.fintrack.dto.*; import br.com.fintrack.service.TransacaoService; import io.swagger.v3.oas.annotations.*; import io.swagger.v3.oas.annotations.responses.*; import io.swagger.v3.oas.annotations.tags.Tag; import jakarta.validation.Valid; import org.springframework.format.annotation.DateTimeFormat; import org.springframework.http.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.time.LocalDate; import java.util.*;
@RestController @RequestMapping("/api/v1/usuarios/{usuarioId}/transacoes") @Tag(name="Transações") @PreAuthorize("#usuarioId == authentication.principal.id") public class TransacaoController{
 private final TransacaoService service; public TransacaoController(TransacaoService s){service=s;}
 @GetMapping @Operation(summary="Listar transações",description="Filtros opcionais por período ou categoria") public List<TransacaoDTO> listar(@PathVariable Long usuarioId,@RequestParam(required=false) @DateTimeFormat(iso=DateTimeFormat.ISO.DATE) LocalDate inicio,@RequestParam(required=false) @DateTimeFormat(iso=DateTimeFormat.ISO.DATE) LocalDate fim,@RequestParam(required=false) Long categoriaId){return service.listar(usuarioId,inicio,fim,categoriaId);}
 @GetMapping("/{id}") @Operation(summary="Buscar transação") public TransacaoDTO buscar(@PathVariable Long usuarioId,@PathVariable Long id){return service.buscar(usuarioId,id);}
 @PostMapping @ResponseStatus(HttpStatus.CREATED) @Operation(summary="Criar transação") @ApiResponses({@ApiResponse(responseCode="201",description="Criada"),@ApiResponse(responseCode="400",description="Validação ou saldo insuficiente"),@ApiResponse(responseCode="401",description="Não autenticado"),@ApiResponse(responseCode="403",description="Outro usuário"),@ApiResponse(responseCode="404",description="Categoria não encontrada")}) public TransacaoDTO criar(@PathVariable Long usuarioId,@Valid @RequestBody TransacaoDTO d){return service.criar(usuarioId,d);}
 @PutMapping("/{id}") @Operation(summary="Atualizar transação") public TransacaoDTO atualizar(@PathVariable Long usuarioId,@PathVariable Long id,@Valid @RequestBody TransacaoDTO d){return service.atualizar(usuarioId,id,d);}
 @DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) @Operation(summary="Remover transação") public void remover(@PathVariable Long usuarioId,@PathVariable Long id){service.remover(usuarioId,id);}
 @GetMapping("/relatorios/saldo") @Operation(summary="Calcular receitas, despesas e saldo") public SaldoDTO saldo(@PathVariable Long usuarioId,@RequestParam(required=false) @DateTimeFormat(iso=DateTimeFormat.ISO.DATE) LocalDate inicio,@RequestParam(required=false) @DateTimeFormat(iso=DateTimeFormat.ISO.DATE) LocalDate fim){return service.saldo(usuarioId,inicio,fim);}
}
